<?php

namespace MongoDB\Driver;

use MongoDB\Driver\Exception\InvalidArgumentException;

/**
 * <div id="class.mongodb-driver-command" class="reference"> <h1 class="title">The MongoDB\Driver\Command class</h1>  <div class="partintro"><p class="verinfo">(mongodb &gt;=1.0.0)</p>  <div class="section" id="mongodb-driver-command.intro">   <h2 class="title">简介</h2>   <p class="simpara">    The <span class="classname"><strong class="classname">MongoDB\Driver\Command</strong></span> class is a value object    that represents a database command.   </p>   <p class="simpara">    To provide <q class="quote">Command Helpers</q> the <span class="classname"><strong class="classname">MongoDB\Driver\Command</strong></span> object should be composed.   </p>  </div>  <div class="section" id="mongodb-driver-command.synopsis">   <h2 class="title">类摘要</h2>   <div class="classsynopsis">    <span class="ooclass"><strong class="classname"></strong></span>    <div class="classsynopsisinfo">     <span class="modifier">final</span>     <span class="ooclass">      <span class="modifier">class</span> <strong class="classname">MongoDB\Driver\Command</strong>     </span>     {</div>    <div class="classsynopsisinfo classsynopsisinfo_comment">// 方法 </div>    <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><a href="https://php.net/manual/zh/mongodb-driver-command.construct.php" class="methodname" style="color:#CC7832">__construct</a></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.object.php" class="type object" style="color:#EAB766">object</a></span></span> <span class="parameter" style="color:#3A95FF">\$document</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span></span> <span class="parameter" style="color:#3A95FF">\$commandOptions</span><span class="initializer"> = <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong></span></span>)</div>   }</div>  </div>  <div class="section" id="mongodb-driver-command.examples">   <h2 class="title">示例</h2>   <div class="example" id="example-1">    <p><strong>示例 #1 Composing <span class="classname"><strong class="classname">MongoDB\Driver\Command</strong></span> to provide a helper to create collections</strong></p>    <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br></span><span style="color: #007700">class </span><span style="color: #9876AA">CreateCollection </span><span style="color: #007700">{<br>    protected </span><span style="color: #9876AA">\$cmd </span><span style="color: #007700">= array();<br><br>    function </span><span style="color: #9876AA">__construct</span><span style="color: #007700">(</span><span style="color: #9876AA">\$collectionName</span><span style="color: #007700">) {<br>        </span><span style="color: #9876AA">\$this</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">cmd</span><span style="color: #007700">[</span><span style="color: #DD0000">"create"</span><span style="color: #007700">] = (string) </span><span style="color: #9876AA">\$collectionName</span><span style="color: #007700">;<br>    }<br>    function </span><span style="color: #9876AA">setCappedCollection</span><span style="color: #007700">(</span><span style="color: #9876AA">\$maxBytes</span><span style="color: #007700">, </span><span style="color: #9876AA">\$maxDocuments </span><span style="color: #007700">= </span><span style="color: #9876AA">false</span><span style="color: #007700">) {<br>        </span><span style="color: #9876AA">\$this</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">cmd</span><span style="color: #007700">[</span><span style="color: #DD0000">"capped"</span><span style="color: #007700">] = </span><span style="color: #9876AA">true</span><span style="color: #007700">;<br>        </span><span style="color: #9876AA">\$this</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">cmd</span><span style="color: #007700">[</span><span style="color: #DD0000">"size"</span><span style="color: #007700">]   = (int) </span><span style="color: #9876AA">\$maxBytes</span><span style="color: #007700">;<br><br>        if (</span><span style="color: #9876AA">\$maxDocuments</span><span style="color: #007700">) {<br>            </span><span style="color: #9876AA">\$this</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">cmd</span><span style="color: #007700">[</span><span style="color: #DD0000">"max"</span><span style="color: #007700">] = (int) </span><span style="color: #9876AA">\$maxDocuments</span><span style="color: #007700">;<br>        }<br>    }<br>    function </span><span style="color: #9876AA">usePowerOf2Sizes</span><span style="color: #007700">(</span><span style="color: #9876AA">\$bool</span><span style="color: #007700">) {<br>        if (</span><span style="color: #9876AA">\$bool</span><span style="color: #007700">) {<br>            </span><span style="color: #9876AA">\$this</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">cmd</span><span style="color: #007700">[</span><span style="color: #DD0000">"flags"</span><span style="color: #007700">] = </span><span style="color: #9876AA">1</span><span style="color: #007700">;<br>        } else {<br>            </span><span style="color: #9876AA">\$this</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">cmd</span><span style="color: #007700">[</span><span style="color: #DD0000">"flags"</span><span style="color: #007700">] = </span><span style="color: #9876AA">0</span><span style="color: #007700">;<br>        }<br>    }<br>    function </span><span style="color: #9876AA">setFlags</span><span style="color: #007700">(</span><span style="color: #9876AA">\$flags</span><span style="color: #007700">) {<br>        </span><span style="color: #9876AA">\$this</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">cmd</span><span style="color: #007700">[</span><span style="color: #DD0000">"flags"</span><span style="color: #007700">] = (int) </span><span style="color: #9876AA">\$flags</span><span style="color: #007700">;<br>    }<br>    function </span><span style="color: #9876AA">getCommand</span><span style="color: #007700">() {<br>        return new </span><span style="color: #9876AA">MongoDB\Driver\Command</span><span style="color: #007700">(</span><span style="color: #9876AA">\$this</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">cmd</span><span style="color: #007700">);<br>    }<br>    function </span><span style="color: #9876AA">getCollectionName</span><span style="color: #007700">() {<br>        return </span><span style="color: #9876AA">\$this</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">cmd</span><span style="color: #007700">[</span><span style="color: #DD0000">"create"</span><span style="color: #007700">];<br>    }<br>}<br><br><br></span><span style="color: #9876AA">\$manager </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\Manager</span><span style="color: #007700">(</span><span style="color: #DD0000">"mongodb://localhost:27017"</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">\$createCollection </span><span style="color: #007700">= new </span><span style="color: #9876AA">CreateCollection</span><span style="color: #007700">(</span><span style="color: #DD0000">"cappedCollection"</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$createCollection</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">setCappedCollection</span><span style="color: #007700">(</span><span style="color: #9876AA">64 </span><span style="color: #007700">* </span><span style="color: #9876AA">1024</span><span style="color: #007700">);<br><br>try {<br>    </span><span style="color: #9876AA">\$command </span><span style="color: #007700">= </span><span style="color: #9876AA">\$createCollection</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getCommand</span><span style="color: #007700">();<br>    </span><span style="color: #9876AA">\$cursor </span><span style="color: #007700">= </span><span style="color: #9876AA">\$manager</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">executeCommand</span><span style="color: #007700">(</span><span style="color: #DD0000">"databaseName"</span><span style="color: #007700">, </span><span style="color: #9876AA">\$command</span><span style="color: #007700">);<br>    </span><span style="color: #9876AA">\$response </span><span style="color: #007700">= </span><span style="color: #9876AA">\$cursor</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">toArray</span><span style="color: #007700">()[</span><span style="color: #9876AA">0</span><span style="color: #007700">];<br>    </span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$response</span><span style="color: #007700">);<br><br>    </span><span style="color: #9876AA">\$collstats </span><span style="color: #007700">= [</span><span style="color: #DD0000">"collstats" </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">\$createCollection</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getCollectionName</span><span style="color: #007700">()];<br>    </span><span style="color: #9876AA">\$cursor </span><span style="color: #007700">= </span><span style="color: #9876AA">\$manager</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">executeCommand</span><span style="color: #007700">(</span><span style="color: #DD0000">"databaseName"</span><span style="color: #007700">, new </span><span style="color: #9876AA">MongoDB\Driver\Command</span><span style="color: #007700">(</span><span style="color: #9876AA">\$collstats</span><span style="color: #007700">));<br>    </span><span style="color: #9876AA">\$response </span><span style="color: #007700">= </span><span style="color: #9876AA">\$cursor</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">toArray</span><span style="color: #007700">()[</span><span style="color: #9876AA">0</span><span style="color: #007700">];<br>    </span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$response</span><span style="color: #007700">);<br>} catch(</span><span style="color: #9876AA">MongoDB\Driver\Exception \$e</span><span style="color: #007700">) {<br>    echo </span><span style="color: #9876AA">\$e</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getMessage</span><span style="color: #007700">(), </span><span style="color: #DD0000">"\n"</span><span style="color: #007700">;<br>    exit;<br>}<br><br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>    </div>   </div>   <p class="simpara">以上示例会输出：</p>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="cdata"><blockquote style="border:1px gray solid;"><br>object(MongoDB\Driver\Command)#3&nbsp;(1)&nbsp;{<br>&nbsp;&nbsp;["command"]=&gt;<br>&nbsp;&nbsp;array(3)&nbsp;{<br>&nbsp;&nbsp;&nbsp;&nbsp;["create"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;string(16)&nbsp;"cappedCollection"<br>&nbsp;&nbsp;&nbsp;&nbsp;["capped"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;bool(true)<br>&nbsp;&nbsp;&nbsp;&nbsp;["size"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;int(65536)<br>&nbsp;&nbsp;}<br>}<br>array(1)&nbsp;{<br>&nbsp;&nbsp;["ok"]=&gt;<br>&nbsp;&nbsp;float(1)<br>}<br>array(16)&nbsp;{<br>&nbsp;&nbsp;["ns"]=&gt;<br>&nbsp;&nbsp;string(29)&nbsp;"databaseName.cappedCollection"<br>&nbsp;&nbsp;["count"]=&gt;<br>&nbsp;&nbsp;int(0)<br>&nbsp;&nbsp;["size"]=&gt;<br>&nbsp;&nbsp;int(0)<br>&nbsp;&nbsp;["numExtents"]=&gt;<br>&nbsp;&nbsp;int(1)<br>&nbsp;&nbsp;["storageSize"]=&gt;<br>&nbsp;&nbsp;int(65536)<br>&nbsp;&nbsp;["nindexes"]=&gt;<br>&nbsp;&nbsp;int(1)<br>&nbsp;&nbsp;["lastExtentSize"]=&gt;<br>&nbsp;&nbsp;float(65536)<br>&nbsp;&nbsp;["paddingFactor"]=&gt;<br>&nbsp;&nbsp;float(1)<br>&nbsp;&nbsp;["paddingFactorNote"]=&gt;<br>&nbsp;&nbsp;string(101)&nbsp;"paddingFactor&nbsp;is&nbsp;unused&nbsp;and&nbsp;unmaintained&nbsp;in&nbsp;2.8.&nbsp;It&nbsp;remains&nbsp;hard&nbsp;coded&nbsp;to&nbsp;1.0&nbsp;for&nbsp;compatibility&nbsp;only."<br>&nbsp;&nbsp;["userFlags"]=&gt;<br>&nbsp;&nbsp;int(0)<br>&nbsp;&nbsp;["capped"]=&gt;<br>&nbsp;&nbsp;bool(true)<br>&nbsp;&nbsp;["max"]=&gt;<br>&nbsp;&nbsp;int(9223372036854775807)<br>&nbsp;&nbsp;["maxSize"]=&gt;<br>&nbsp;&nbsp;int(65536)<br>&nbsp;&nbsp;["totalIndexSize"]=&gt;<br>&nbsp;&nbsp;int(8176)<br>&nbsp;&nbsp;["indexSizes"]=&gt;<br>&nbsp;&nbsp;object(stdClass)#4&nbsp;(1)&nbsp;{<br>&nbsp;&nbsp;&nbsp;&nbsp;["_id_"]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;int(8176)<br>&nbsp;&nbsp;}<br>&nbsp;&nbsp;["ok"]=&gt;<br>&nbsp;&nbsp;float(1)<br>}<br></blockquote></div>   </div>  </div> </div> <h2>目录</h2><ul class="chunklist chunklist_reference"><li>{@link MongoDB\Driver\Command::__construct} — Create a new Command</li></ul></div>
 * 
 * The MongoDB\Driver\Command class is a value object that represents a database command.
 * To provide "Command Helpers" the MongoDB\Driver\Command object should be composed.
 * @link https://php.net/manual/zh/class.mongodb-driver-command.php
 * @since 1.0.0
 */
final class Command
{
    /**
 * <div id="mongodb-driver-command.construct" class="refentry"> <div class="refnamediv">  <h1 class="refname">MongoDB\Driver\Command::__construct</h1>  <p class="verinfo">(mongodb &gt;=1.0.0)</p><p class="refpurpose"><span class="refname">MongoDB\Driver\Command::__construct</span> — <span class="dc-title">Create a new Command</span></p> </div> <div class="refsect1 description" id="refsect1-mongodb-driver-command.construct-description">  <h3 class="title">说明</h3>  <div class="methodsynopsis dc-description">   <span class="modifier">final</span> <span class="modifier">public</span> <span class="modifier">function</span> <span class="methodname" style="color:#CC7832"><strong>MongoDB\Driver\Command::__construct</strong></span>(<span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span>|<span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.object.php" class="type object" style="color:#EAB766">object</a></span></span> <span class="parameter" style="color:#3A95FF">\$document</span></span>, <span class="methodparam"><span class="type" style="color:#EAB766"><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.null.php" class="type null" style="color:#EAB766">?</a></span><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.array.php" class="type array" style="color:#EAB766">array</a></span></span> <span class="parameter" style="color:#3A95FF">\$commandOptions</span><span class="initializer"> = <strong><span><a href="https://php.net/manual/zh/reserved.constants.php#constant.null">null</a></span></strong></span></span>)</div>  <p class="simpara">   Constructs a new <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-command.php" class="classname">MongoDB\Driver\Command</a></span>, which is an   immutable value object that represents a database command. The command may   then be executed with   <span class="methodname" style="color:#CC7832">{@link MongoDB\Driver\Manager::executeCommand()}</span>.  </p>  <p class="simpara">   The complete command document, which includes the command name and its   options, should be expressed in the <span class="parameter" style="color:#3A95FF">document</span>   parameter. The <span class="parameter" style="color:#3A95FF">commandOptions</span> parameter is only used   to specify options related to the execution of the command and the resulting   <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-cursor.php" class="classname">MongoDB\Driver\Cursor</a></span>.  </p> </div> <div class="refsect1 parameters" id="refsect1-mongodb-driver-command.construct-parameters">  <h3 class="title">参数</h3>  <dl>       <dt><span class="parameter" style="color:#3A95FF">document</span></dt>    <dd>     <span class="simpara">      The complete command document, which will be sent to the server.     </span>    </dd>          <dt><span class="parameter" style="color:#3A95FF">commandOptions</span></dt>    <dd>     <blockquote class="note" style="border:1px gray solid"><p><strong class="note" style="border:1px gray solid">注意</strong>:       <span class="simpara">       Do not use this parameter to specify options described in the command's       reference in the MongoDB manual. This parameter should only be used for       the options explicitly listed below.      </span>     </p></blockquote>     <p class="para">      </p><table class="doctable table">       <caption><strong>commandOptions</strong></caption>               <thead>         <tr>          <th>Option</th>          <th>Type</th>          <th>Description</th>         </tr>        </thead>        <tbody class="tbody">         <tr>          <td>maxAwaitTimeMS</td>          <td><span class="type" style="color:#EAB766"><a href="https://php.net/manual/zh/language.types.integer.php" class="type int" style="color:#EAB766">int</a></span></td>          <td>           <span class="simpara">            Positive integer denoting the time limit in milliseconds for the            server to block a getMore operation if no data is available. This            option should only be used in conjunction with commands that return            a tailable cursor (e.g. <a href="https://www.mongodb.com/docs/manual/changeStreams/" class="link external">»&nbsp;Change            Streams</a>).           </span>          </td>         </tr>        </tbody>             </table>         </dd>     </dl> </div> <div class="refsect1 errors" id="refsect1-mongodb-driver-command.construct-errors">  <h3 class="title">错误／异常</h3>  <ul class="simplelist">   <li>Throws <span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-exception-invalidargumentexception.php" class="classname">MongoDB\Driver\Exception\InvalidArgumentException</a></span> on argument parsing errors.</li>  </ul> </div> <div class="refsect1 changelog" id="refsect1-mongodb-driver-command.construct-changelog">  <h3 class="title">更新日志</h3>  <table class="doctable informaltable">       <thead>     <tr>      <th>版本</th>      <th>说明</th>     </tr>    </thead>    <tbody class="tbody">     <tr>      <td>PECL mongodb 1.4.0</td>      <td>       <span class="simpara">        Added a second <span class="parameter" style="color:#3A95FF">commandOptions</span> argument, which supports        the <span class="literal">"maxAwaitTimeMS"</span> option.       </span>      </td>     </tr>    </tbody>     </table> </div> <div class="refsect1 examples" id="refsect1-mongodb-driver-command.construct-examples">  <h3 class="title">示例</h3>  <div class="example" id="example-2">   <p><strong>示例 #1 <span class="function"><strong style="color:#CC7832">MongoDB\Driver\Command::__construct()</strong></span> example</strong></p>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br><br>\$manager </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\Manager</span><span style="color: #007700">(</span><span style="color: #DD0000">"mongodb://localhost:27017"</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$command </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\Command</span><span style="color: #007700">(array(</span><span style="color: #DD0000">"buildinfo" </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">1</span><span style="color: #007700">));<br><br>try {<br>    </span><span style="color: #9876AA">\$cursor </span><span style="color: #007700">= </span><span style="color: #9876AA">\$manager</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">executeCommand</span><span style="color: #007700">(</span><span style="color: #DD0000">"admin"</span><span style="color: #007700">, </span><span style="color: #9876AA">\$command</span><span style="color: #007700">);<br>    </span><span style="color: #9876AA">\$response </span><span style="color: #007700">= </span><span style="color: #9876AA">\$cursor</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">toArray</span><span style="color: #007700">()[</span><span style="color: #9876AA">0</span><span style="color: #007700">];<br>} catch(</span><span style="color: #9876AA">MongoDB\Driver\Exception \$e</span><span style="color: #007700">) {<br>    echo </span><span style="color: #9876AA">\$e</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getMessage</span><span style="color: #007700">(), </span><span style="color: #DD0000">"\n"</span><span style="color: #007700">;<br>    exit;<br>}<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$response</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><div class="examplescode"><blockquote style="border:1px gray solid;">array(13)&nbsp;{<br>&nbsp;&nbsp;["version"]=&gt;<br>&nbsp;&nbsp;string(14)&nbsp;"2.8.0-rc2-pre-"<br>&nbsp;&nbsp;["gitVersion"]=&gt;<br>&nbsp;&nbsp;string(62)&nbsp;"b743d7158f7642f4da6b7eac8320374b3b88dc2e&nbsp;modules:&nbsp;subscription"<br>&nbsp;&nbsp;["OpenSSLVersion"]=&gt;<br>&nbsp;&nbsp;string(25)&nbsp;"OpenSSL&nbsp;1.0.1f&nbsp;6&nbsp;Jan&nbsp;2014"<br>&nbsp;&nbsp;["sysInfo"]=&gt;<br>&nbsp;&nbsp;string(104)&nbsp;"Linux&nbsp;infant&nbsp;3.16.0-24-generic&nbsp;#32-Ubuntu&nbsp;SMP&nbsp;Tue&nbsp;Oct&nbsp;28&nbsp;13:07:32&nbsp;UTC&nbsp;2014&nbsp;x86_64&nbsp;BOOST_LIB_VERSION=1_49"<br>&nbsp;&nbsp;["loaderFlags"]=&gt;<br>&nbsp;&nbsp;string(91)&nbsp;"-fPIC&nbsp;-pthread&nbsp;-Wl,-z,now&nbsp;-rdynamic&nbsp;-Wl,-Bsymbolic-functions&nbsp;-Wl,-z,relro&nbsp;-Wl,-z,now&nbsp;-Wl,-E"<br>&nbsp;&nbsp;["compilerFlags"]=&gt;<br>&nbsp;&nbsp;string(301)&nbsp;"-Wnon-virtual-dtor&nbsp;-Woverloaded-virtual&nbsp;-std=c++11&nbsp;-fPIC&nbsp;-fno-strict-aliasing&nbsp;-ggdb&nbsp;-pthread&nbsp;-Wall&nbsp;-Wsign-compare&nbsp;-Wno-unknown-pragmas&nbsp;-Winvalid-pch&nbsp;-pipe&nbsp;-Werror&nbsp;-O3&nbsp;-Wno-unused-local-typedefs&nbsp;-Wno-unused-function&nbsp;-Wno-deprecated-declarations&nbsp;-Wno-unused-but-set-variable&nbsp;-fno-builtin-memcmp&nbsp;-std=c99"<br>&nbsp;&nbsp;["allocator"]=&gt;<br>&nbsp;&nbsp;string(8)&nbsp;"tcmalloc"<br>&nbsp;&nbsp;["versionArray"]=&gt;<br>&nbsp;&nbsp;array(4)&nbsp;{<br>&nbsp;&nbsp;&nbsp;&nbsp;[0]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;int(2)<br>&nbsp;&nbsp;&nbsp;&nbsp;[1]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;int(8)<br>&nbsp;&nbsp;&nbsp;&nbsp;[2]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;int(0)<br>&nbsp;&nbsp;&nbsp;&nbsp;[3]=&gt;<br>&nbsp;&nbsp;&nbsp;&nbsp;int(-8)<br>&nbsp;&nbsp;}<br>&nbsp;&nbsp;["javascriptEngine"]=&gt;<br>&nbsp;&nbsp;string(2)&nbsp;"V8"<br>&nbsp;&nbsp;["bits"]=&gt;<br>&nbsp;&nbsp;int(64)<br>&nbsp;&nbsp;["debug"]=&gt;<br>&nbsp;&nbsp;bool(false)<br>&nbsp;&nbsp;["maxBsonObjectSize"]=&gt;<br>&nbsp;&nbsp;int(16777216)<br>&nbsp;&nbsp;["ok"]=&gt;<br>&nbsp;&nbsp;float(1)<br>}</blockquote></div>   </div>  </div>  <div class="example" id="example-3">   <p><strong>示例 #2 <span class="function"><strong style="color:#CC7832">MongoDB\Driver\Command::__construct()</strong></span> example</strong></p>   <div class="example-contents"><p>    Commands can accept options as well, as part of the normal structure that    you create to send to the server. For example, the    <span class="literal">maxTimeMS</span> option can be passed with most commands to    restrict the amount of time a specific command can run for on the server.   </p></div>   <div class="example-contents"><div class="phpcode" style="border-color:gray;background:#1E1F22;"><blockquote style="border:1px gray solid;white-space:pre-wrap"><span style="color: #000000"><span style="color: #9876AA">&lt;?php<br><br>\$manager </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\Manager</span><span style="color: #007700">(</span><span style="color: #DD0000">"mongodb://localhost:27017"</span><span style="color: #007700">);<br></span><span style="color: #9876AA">\$command </span><span style="color: #007700">= new </span><span style="color: #9876AA">MongoDB\Driver\Command</span><span style="color: #007700">(<br>    array(<br>        </span><span style="color: #DD0000">"distinct" </span><span style="color: #007700">=&gt; </span><span style="color: #DD0000">"beer"</span><span style="color: #007700">,<br>        </span><span style="color: #DD0000">"key" </span><span style="color: #007700">=&gt; </span><span style="color: #DD0000">"beer_name"</span><span style="color: #007700">,<br>        </span><span style="color: #DD0000">"maxTimeMS" </span><span style="color: #007700">=&gt; </span><span style="color: #9876AA">10</span><span style="color: #007700">,<br>    )<br>);<br><br>try {<br>    </span><span style="color: #9876AA">\$cursor </span><span style="color: #007700">= </span><span style="color: #9876AA">\$manager</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">executeCommand</span><span style="color: #007700">(</span><span style="color: #DD0000">"beerdb"</span><span style="color: #007700">, </span><span style="color: #9876AA">\$command</span><span style="color: #007700">);<br>    </span><span style="color: #9876AA">\$response </span><span style="color: #007700">= </span><span style="color: #9876AA">\$cursor</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">toArray</span><span style="color: #007700">()[</span><span style="color: #9876AA">0</span><span style="color: #007700">];<br>} catch(</span><span style="color: #9876AA">MongoDB\Driver\Exception\Exception \$e</span><span style="color: #007700">) {<br>    echo </span><span style="color: #9876AA">\$e</span><span style="color: #007700">-&gt;</span><span style="color: #9876AA">getMessage</span><span style="color: #007700">(), </span><span style="color: #DD0000">"\n"</span><span style="color: #007700">;<br>    exit;<br>}<br></span><span style="color: #9876AA">var_dump</span><span style="color: #007700">(</span><span style="color: #9876AA">\$response</span><span style="color: #007700">);<br><br></span><span style="color: #9876AA">?&gt;</span></span></blockquote></div>   </div>   <div class="example-contents"><p>以上示例的输出类似于：</p></div>   <div class="example-contents screen" style="border-color:gray;background:#1E1F22;"><br>    operation exceeded time limit<br>   </div>  </div> </div> <div class="refsect1 seealso" id="refsect1-mongodb-driver-command.construct-seealso">  <h3 class="title">参见</h3>  <ul class="simplelist">   <li><span class="methodname" style="color:#CC7832">{@link MongoDB\Driver\Manager::executeCommand()} - Execute a database command</span></li>   <li><span class="classname"><a href="https://php.net/manual/zh/class.mongodb-driver-cursor.php" class="classname">MongoDB\Driver\Cursor</a></span></li>  </ul> </div></div>
 * 
     * Construct new Command
     * @param array|object $document The complete command to construct
     * @param array|null $commandOptions Do not use this parameter to specify options described in the command's reference in the MongoDB manual.
     * @throws InvalidArgumentException on argument parsing errors.
     * @link https://secure.php.net/manual/en/mongodb-driver-command.construct.php
     * @since 1.0.0
     */
    final public function __construct(array|object $document, ?array $commandOptions = null) {}


    final public function __wakeup() {}
}
